function onPreviewState(state){if(state.documentId!==workspace.activeId)return;if(state.kind==='updated'&&state.revision<workspace.active.requestedRevision)return;C('compile-status').textContent=state.message;C('compile-status').dataset.error=String(['error','invalid'].includes(state.kind));C('preview-badge').textContent=(state.stale?'上次成功结果 · ':'')+state.message;C('preview-badge').dataset.kind=state.kind;C('preview-empty').hidden=!['empty','invalid'].includes(state.kind)||!!state.stale;C('preview-empty').querySelector('p').textContent=state.message;C('export-formula').disabled=['empty','invalid','error','compiling'].includes(state.kind);}
preview=new GenleGraphPreview(C('graph-preview'),{onState:onPreviewState,onFrame(frame){if(frame.documentId!==workspace.activeId)return;C('runtime-diagnostics').textContent=JSON.stringify({文档:frame.documentId,文档参数版本:workspace.active.revision,画面版本:frame.revision,实际绘制:frame.draws,着色器编译:frame.compiles,参数批次:frame.patches,更新提交延迟毫秒:Math.round(frame.latency),正在编译:preview.busy},null,2);},onCamera(camera){if(workspace.activeId!==preview.docId)return;workspace.active.preview.camera=camera;saveSoon();}});
for(const b of document.querySelectorAll('[data-new]'))b.onclick=()=>newDocument(b.dataset.new);
C('duplicate-document').onclick=()=>{try{flushPatches();const doc=workspace.duplicate();C('new-menu').open=false;activateDocument(doc.id);}catch(e){connectionMessage(e.message);}};C('restore-document').onclick=()=>{const doc=workspace.reopen();if(doc)activateDocument(doc.id);C('new-menu').open=false;};C('formula-name').onchange=()=>renameDocument(C('formula-name').value);
C('add-node').onclick=()=>openLibrary(selectedEdge?{edge:JSON.parse(selectedEdge)}:null);C('blank-add').onclick=()=>openLibrary();C('empty-add-input').onclick=()=>{if(!workspace.active.graph.nodes.some(n=>n.type==='orbit-input'))addNode('orbit-input');else openLibrary();};C('close-library').onclick=()=>{C('node-library').hidden=true;graphCanvas.focus();};C('node-search').oninput=renderLibrary;
C('toggle-inspector').onclick=()=>advancedOpen(C('composer-inspector').hidden);C('close-inspector').onclick=()=>advancedOpen(false);C('delete-selection').onclick=removeSelection;C('fit-composer').onclick=()=>focusNodes(true);C('focus-selection').onclick=()=>focusNodes();
C('undo-graph').onclick=()=>{flushPatches();if(workspace.active.undo()){renderScene();renderInspector();updateUndo();saveSoon();workspace.active.requestedRevision=workspace.active.revision;preview.setGraph(workspace.active.graph,workspace.active.revision);}};C('redo-graph').onclick=()=>{if(workspace.active.redo()){renderScene();renderInspector();updateUndo();saveSoon();workspace.active.requestedRevision=workspace.active.revision;preview.setGraph(workspace.active.graph,workspace.active.revision);}};
C('auto-layout').onclick=()=>editGraph(g=>{arrangeNodes(g);},{math:false});
C('graph-quality').onchange=()=>{workspace.active.preview.quality=Number(C('graph-quality').value);preview.setQuality(workspace.active.preview.quality);saveSoon();};for(const [id,name]of [['reference-camera','reference'],['top-camera','top'],['bottom-camera','bottom']])C(id).onclick=()=>preview.view(name);
C('preview-maximize').onclick=()=>{const active=document.body.classList.toggle('preview-expanded');C('preview-maximize').setAttribute('aria-pressed',String(active));C('preview-maximize').textContent=active?'返回节点':'展开 3D';};
C('graph-png').onclick=async()=>{try{const blob=await preview.snapshot();if(!blob)throw Error('没有可保存的画面。');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='genle-fractal.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){connectionMessage(e.message);}};
C('recover-preview').onclick=async()=>{await saveWorkspace();location.reload();};C('save-project').onclick=exportProject;C('export-formula').onclick=exportFormula;C('export-graph').onclick=exportGraph;C('open-studio').onclick=()=>{try{const pack=G.package(D.renderable(workspace.active.graph)),id=crypto.randomUUID();sessionStorage.setItem('genle-graph-open-'+id,JSON.stringify(pack));saveWorkspace().then(()=>{location.href='index.html?graph-session='+id;});}catch(e){connectionMessage(e.message);}};
C('import-project').onclick=()=>C('workspace-file').click();C('workspace-file').onchange=async()=>{const file=C('workspace-file').files[0];if(!file)return;try{await importFile(file);}catch(e){connectionMessage('导入失败：'+e.message);}C('workspace-file').value='';};
const divider=C('workspace-divider');divider.onpointerdown=e=>{divider.setPointerCapture(e.pointerId);divider.dataset.resizing='true';};divider.onpointermove=e=>{if(divider.dataset.resizing!=='true')return;const r=C('workspace-layout').getBoundingClientRect(),percent=Math.max(25,Math.min(62,(e.clientX-r.left)/r.width*100));document.documentElement.style.setProperty('--preview-width',percent+'%');};divider.onpointerup=()=>{delete divider.dataset.resizing;try{localStorage.setItem('genle-composer-layout-width',document.documentElement.style.getPropertyValue('--preview-width'));}catch(_){}};divider.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const current=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--preview-width'))||36;document.documentElement.style.setProperty('--preview-width',Math.max(25,Math.min(62,current+(e.key==='ArrowRight'?2:-2)))+'%');}};
try{const accent=localStorage.getItem('genle-fractal-accent'),width=localStorage.getItem('genle-composer-layout-width');if(/^#[0-9a-f]{6}$/i.test(accent||'')){document.documentElement.style.setProperty('--accent',accent);C('composer-accent').value=accent;}if(/^\d+(\.\d+)?%$/.test(width||''))document.documentElement.style.setProperty('--preview-width',width);}catch(_){}
C('composer-accent').oninput=e=>{document.documentElement.style.setProperty('--accent',e.target.value);try{localStorage.setItem('genle-fractal-accent',e.target.value);}catch(_){}};
document.addEventListener('visibilitychange',()=>{if(document.hidden){endParameterEdit();flushPatches();saveWorkspace();}});window.addEventListener('pagehide',()=>{clearTimeout(saveTimer);try{repository.checkpoint(workspace.serialize());}catch(_){}repository.write(workspace.serialize()).catch(()=>{});});
(async()=>{try{const saved=await repository.read();if(saved)workspace.load(saved);else{let legacy;try{const text=localStorage.getItem('genle-composer-graph-v1');if(text)legacy=D.asDraft(JSON.parse(text));}catch(e){connectionMessage('旧草稿读取失败，原数据已保留。'+e.message);}workspace.add('copy',legacy||G.example('uber'));workspace.active.editor.needsLayout=true;}activateDocument(workspace.activeId);}catch(e){repository.recovery=true;connectionMessage('工作区恢复失败，原数据未覆盖：'+e.message);workspace.add();activateDocument(workspace.activeId);}})();
